styles:
/* One stable coordinate system. The sampled rig owns hand/prop contact; CSS
   only supplies small independent ambient rhythms with matching endpoints. */
.scene-rig { pointer-events:none; stroke-linecap:round; stroke-linejoin:round; --scene-blue:#79baf0; --scene-line:#3977af; --scene-ink:#204b72; --scene-pale:#ddf1ff; --scene-wood:#f2d8bd; --scene-edge:#e9bf8b; --scene-green:#aed7be; --scene-paper:#fff8e8; --scene-pink:#ffc3b6; }
.scene-draw-body { fill:var(--scene-coat,var(--scene-blue)); stroke:var(--scene-line); stroke-width:1.5; }
.scene-draw-shade { fill:#5097dc; stroke:var(--scene-line); stroke-width:1.5; }
.scene-draw-belly { fill:var(--scene-belly,var(--scene-pale)); }
.scene-draw-highlight { fill:#b7e0ff; }
.scene-draw-glint { fill:white; }
.scene-draw-line,.scene-draw-softline { fill:none; stroke:var(--scene-line); stroke-width:1.6; }
.scene-draw-softline { stroke-opacity:.65;stroke-width:1.2; }
.scene-draw-ink { fill:var(--scene-ink); }
.scene-draw-face { fill:none;stroke:var(--scene-ink);stroke-width:2.4; }
.scene-draw-pink { fill:var(--scene-pink); }
.scene-draw-shadow { fill:#796e67;opacity:.17; }
.scene-draw-table { fill:var(--scene-wood);stroke:#997d68;stroke-width:1.5; }
.scene-draw-edge { fill:var(--scene-edge);stroke:#9a7960;stroke-width:1.5; }
.scene-draw-green { fill:var(--scene-green);stroke:var(--scene-line);stroke-width:1.5; }
.scene-draw-paper { fill:var(--scene-paper);stroke:var(--scene-line);stroke-width:1.5; }
.scene-draw-water { fill:#d5ecfb;stroke:var(--scene-line);stroke-width:1.4; }
.scene-draw-light { fill:var(--scene-pale);stroke:var(--scene-line);stroke-width:1.4; }
.scene-draw-steam { fill:none;stroke:#6f93b3;stroke-width:2; }
.scene-draw-handle { fill:none;stroke:var(--scene-line);stroke-width:3; }
/* The water's own fall takes a moment, however slowly the kettle tips: the front runs
   down from the spout under gravity when the pour starts, and the tail falls after it ends. */
.scene-draw-pour { fill:none;stroke:#d29e54;stroke-width:2;stroke-dasharray:1 1;stroke-dashoffset:1;opacity:0; }
.scene-draw-pour[data-pour='pouring'] { stroke-dashoffset:0;opacity:1;transition:stroke-dashoffset 260ms cubic-bezier(.55,0,1,.6); }
.scene-draw-pour[data-pour='done'] { stroke-dashoffset:-1;transition:stroke-dashoffset 220ms cubic-bezier(.55,0,1,.6),opacity 0ms 220ms; }
/* A piece that slides out of a tipped bowl falls in its own time, like the water: it starts at
   the bowl's lip and drops under gravity, however slowly the session tips the bowl. */
.scene-fall { transform:translate(var(--fall-x),var(--fall-y)); opacity:0; }
.scene-fall[data-landed='true'] { transform:none; opacity:1; transition:transform 300ms cubic-bezier(.55,0,1,.6); }
.scene-rig [data-scene-part='ground'] .scene-draw-softline { stroke:#ac9985; stroke-opacity:.32; }
.scene-rig-steam { animation:scene-rig-steam 4s ease-in-out infinite; transform-box:fill-box;transform-origin:center bottom; }
.scene-rig[data-scene-part="scene-R2"] .scene-rig-look { animation:scene-rig-watch 16s ease-in-out infinite; }
.scene-rig-cloud { animation:scene-rig-cloud 16s ease-in-out infinite; }
.scene-rig-bubble { animation:scene-rig-bubble 8s ease-in-out infinite; }
.scene-rig-star { animation:scene-rig-star 7s ease-in-out infinite; }
/* The torso breathes about its feet and keeps its volume: taller means slightly narrower.
   Large enough to see on a phone, unlike the earlier sub-pixel loop this replaced. Feet and
   arms stay put, so held props stay in hand. The gestures in a session come from the timer. */
.scene-rig-breath { transform-origin:120px 164px; animation:scene-rig-breathe var(--blue-breathing,4800ms) cubic-bezier(.37,0,.63,1) infinite; }
.scene-rig-eyes { animation:scene-rig-blink 6.8s linear infinite; transform-origin:120px 95px; }
.blue-companion[data-scene-motion='false'] .scene-rig * { animation-play-state:paused; }
/* Closed and happy eyes don't blink, and a pause never freezes open eyes half shut. */
.scene-rig-eyes:has(> [data-part='eyesHappy'], > [data-part='eyesResting']), .blue-companion[data-scene-motion='false'] .scene-rig-eyes { animation:none; }
.blue-companion[data-static='true'] .scene-rig *, .blue-companion[data-stance='neutral'] .scene-rig * { animation:none!important;transition:none!important; }
/* Loops animate `transform` on groups without a transform attribute of their own. */
@keyframes scene-rig-steam { 0%,100%{transform:translate(0,0);opacity:.65}50%{transform:translate(1px,-2px);opacity:.9} }
@keyframes scene-rig-cloud { 0%,100%{transform:translate(0,0)}50%{transform:translate(5px,0)} }
@keyframes scene-rig-bubble { 0%,100%{transform:translate(0,0)}50%{transform:translate(1px,-3px)} }
@keyframes scene-rig-star { 0%,100%{opacity:.75}50%{opacity:1} }
@keyframes scene-rig-breathe { 0%,100%{transform:scale(1,1)}50%{transform:scale(.993,1.015)} }
/* Close quickly, rest a moment, open more slowly. */
@keyframes scene-rig-blink { 0%,43.6%{transform:scale(1,1);animation-timing-function:cubic-bezier(.5,0,1,1)}45%{transform:scale(1,.12);animation-timing-function:linear}45.6%{transform:scale(1,.12);animation-timing-function:cubic-bezier(0,0,.4,1)}48.6%,100%{transform:scale(1,1)} }
@media(prefers-reduced-motion:reduce){.scene-rig *{animation:none!important;transition:none!important}}

@keyframes scene-rig-watch { 0%,100%{transform:translate(0,0)}50%{transform:translate(2px,0)} }

.scene-rig * {animation:none!important;transition:none!important}
